import{_ as a,o as i,c as l,a2 as o}from"./chunks/framework.DpXDHk3d.js";const g=JSON.parse('{"title":"10.1 照明基础知识与质量指标","description":"","frontmatter":{},"headers":[],"relativePath":"electrician/low-voltage-electrician/10-chapter-10-dian-qi-zhao-ming/10-1-zhao-ming-ji-chu-zhi-shi-yu-zhi-liang-zhi-biao.md","filePath":"electrician/low-voltage-electrician/10-chapter-10-dian-qi-zhao-ming/10-1-zhao-ming-ji-chu-zhi-shi-yu-zhi-liang-zhi-biao.md","lastUpdated":1793096070000}'),r={name:"electrician/low-voltage-electrician/10-chapter-10-dian-qi-zhao-ming/10-1-zhao-ming-ji-chu-zhi-shi-yu-zhi-liang-zhi-biao.md"};function e(n,t,h,s,d,u){return i(),l("div",null,[...t[0]||(t[0]=[o('<h1 id="_10-1-照明基础知识与质量指标" tabindex="-1">10.1 照明基础知识与质量指标 <a class="header-anchor" href="#_10-1-照明基础知识与质量指标" aria-label="Permalink to &quot;10.1 照明基础知识与质量指标&quot;">​</a></h1><h2 id="本节导读" tabindex="-1">本节导读 <a class="header-anchor" href="#本节导读" aria-label="Permalink to &quot;本节导读&quot;">​</a></h2><p>照明不只是&quot;亮不亮&quot;的问题,还有&quot;够不够亮、颜色正不正、刺不刺眼&quot;。这一节认识照明的几个基本物理量,以及衡量照明质量的三个指标。</p><h2 id="一、照明的基本物理量-概念为主" tabindex="-1">一、照明的基本物理量(概念为主) <a class="header-anchor" href="#一、照明的基本物理量-概念为主" aria-label="Permalink to &quot;一、照明的基本物理量(概念为主)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>名称</th><th>符号/单位</th><th>通俗理解</th></tr></thead><tbody><tr><td><strong>光通量</strong></td><td>Φ,单位<strong>流明(lm)</strong></td><td>光源发出的光&quot;总量&quot;</td></tr><tr><td><strong>照度</strong></td><td>E,单位<strong>勒克斯(lx)</strong></td><td>光落到被照面的&quot;多少&quot;,1 lm 光通量均匀照在 1 m² 面积上就是 1 lx</td></tr><tr><td><strong>光强</strong></td><td>I,单位<strong>坎德拉(cd)</strong></td><td>光在某个方向上的&quot;集中程度&quot;</td></tr><tr><td><strong>亮度</strong></td><td>L,单位 cd/m²</td><td>人眼看到的物体表面&quot;亮不亮&quot;</td></tr></tbody></table><blockquote><p>💡 通俗记:<strong>光通量是&quot;源头发了多少光&quot;,照度是&quot;台面上得到多少光&quot;</strong>。同样的灯,离得远、照的面积大,照度就低。</p></blockquote><h2 id="二、常用照明场所的照度要求-了解" tabindex="-1">二、常用照明场所的照度要求(了解) <a class="header-anchor" href="#二、常用照明场所的照度要求-了解" aria-label="Permalink to &quot;二、常用照明场所的照度要求(了解)&quot;">​</a></h2><ul><li>一般办公室、教室:约 300 lx;</li><li>精密作业(绘图、检验):需要更高照度(500 lx 以上);</li><li>走廊、仓库:较低照度即可。</li></ul><blockquote><p>💡 照度不够,人眼疲劳、易出错;照度太高也浪费、刺眼。选灯按场所需要。</p></blockquote><h2 id="三、照明质量的三个指标-重点" tabindex="-1">三、照明质量的三个指标(重点) <a class="header-anchor" href="#三、照明质量的三个指标-重点" aria-label="Permalink to &quot;三、照明质量的三个指标(重点)&quot;">​</a></h2><h3 id="_1-显色性-显色指数-ra" tabindex="-1">1. 显色性(显色指数 Ra) <a class="header-anchor" href="#_1-显色性-显色指数-ra" aria-label="Permalink to &quot;1. 显色性(显色指数 Ra)&quot;">​</a></h3><p>光源还原物体真实颜色的能力:</p><ul><li>满分 100,越接近太阳光(100)颜色越真实;</li><li>需要辨色的场所(如检验、手术、服装)用<strong>高显色性</strong>光源(Ra≥80);</li><li>普通场所要求可降低。</li></ul><h3 id="_2-眩光" tabindex="-1">2. 眩光 <a class="header-anchor" href="#_2-眩光" aria-label="Permalink to &quot;2. 眩光&quot;">​</a></h3><p>光源太亮或直射眼睛,让人看不清、刺眼的现象叫<strong>眩光</strong>:</p><ul><li>减少眩光:灯具加<strong>遮光罩、灯罩</strong>,避免灯具直射眼,降低安装高度不当、避免镜面反射。</li></ul><h3 id="_3-频闪-频闪效应" tabindex="-1">3. 频闪(频闪效应) <a class="header-anchor" href="#_3-频闪-频闪效应" aria-label="Permalink to &quot;3. 频闪(频闪效应)&quot;">​</a></h3><p>光源亮度周期性波动,人眼看高速转动的物体时会觉得&quot;转动得很慢或不动&quot;,这种现象叫<strong>频闪效应</strong>:</p><ul><li>荧光灯(日光灯)用电感镇流器时有明显频闪;</li><li>频闪会让人眼疲劳,也影响高速观察;</li><li>解决:<strong>电子镇流器 / 高频电源</strong>、LED 灯,可明显消除频闪。</li></ul><h2 id="四、光源的色温" tabindex="-1">四、光源的色温 <a class="header-anchor" href="#四、光源的色温" aria-label="Permalink to &quot;四、光源的色温&quot;">​</a></h2><p>色温描述光线的&quot;冷暖&quot;:</p><ul><li>低色温(约 2700K):偏黄、温暖(白炽灯、暖黄光);</li><li>高色温(约 5000K 以上):偏蓝白、清爽(冷白光)。</li></ul><blockquote><p>💡 家用卧室偏暖光舒适,车间、办公偏冷白光清晰。</p></blockquote><h2 id="五、考点提示" tabindex="-1">五、考点提示 <a class="header-anchor" href="#五、考点提示" aria-label="Permalink to &quot;五、考点提示&quot;">​</a></h2><ul><li>✅ 光通量单位 <strong>lm</strong>,照度单位 <strong>lx</strong>。</li><li>✅ 显色指数:辨色场所要<strong>高显色</strong>(Ra 高)。</li><li>✅ 频闪用<strong>电子镇流器/高频</strong>解决。</li><li>✅ 眩光:用灯罩遮挡,避免直射。</li><li>⚠️ 易混点:光通量(光源发多少)vs 照度(表面得多少)单位不同、含义不同。</li></ul><h2 id="六、本节小结" tabindex="-1">六、本节小结 <a class="header-anchor" href="#六、本节小结" aria-label="Permalink to &quot;六、本节小结&quot;">​</a></h2><ul><li>照明的基本量:光通量、照度、光强、亮度。</li><li>照明质量看:显色性、眩光、频闪。</li><li>不同场所选不同的照度、色温、显色性。</li></ul><h2 id="七、自测练习" tabindex="-1">七、自测练习 <a class="header-anchor" href="#七、自测练习" aria-label="Permalink to &quot;七、自测练习&quot;">​</a></h2><ol><li>(单选)照度的单位是()。 A. 流明(lm)　B. 勒克斯(lx)　C. 坎德拉(cd)　D. 瓦特(W)</li><li>(判断)光通量相同的光源,照射面积越大,照度越低。( )</li><li>(单选)需要辨别颜色的场所,应选用()的光源。 A. 显色性高　B. 光通量小　C. 色温低　D. 功率小</li><li>(判断)灯具加灯罩可以减小眩光。( )</li><li>(单选)电感镇流器日光灯的频闪,常用()解决。 A. 加大功率　B. 电子镇流器(高频)　C. 降低电压　D. 加灯罩</li></ol><details><summary>参考答案(点击展开)</summary><ol><li><strong>B</strong>。照度单位是勒克斯(lx)。</li><li><strong>√</strong>。面积越大,单位面积得到的光越少,照度越低。</li><li><strong>A</strong>。辨色场所要高显色性光源。</li><li><strong>√</strong>。灯罩、遮光罩可减小眩光。</li><li><strong>B</strong>。电子镇流器/高频电源可消除频闪。</li></ol></details>',30)])])}const q=a(r,[["render",e]]);export{g as __pageData,q as default};
